javascript:(async()=>{const log=(...a)=>console.log("[GBP Bookmarklet]",...a);log("Starting",location.href);const r=/https:\/\/lh\d\.googleusercontent\.com\/[^\s"'<>\\]+/g;const d=t=>t.replace(/\\\//g,"/").replace(/\\\\u003d|\\u003d/g,"=").replace(/\\\\u0026|\\u0026/g,"&").replace(/\\\\u003f|\\u003f/g,"?");const s=u=>{if(!u||!u.includes("googleusercontent.com"))return u;let t=u.replace(/\/s\d+(-[a-z]+)?\//g,"/s0/");t=t.replace(/=([swh]\d+[^&]*)$/,"=s0");if(!/=s0$/.test(t)&&!/=[swh]\d/.test(t))t+="=s0";return t};const h=async()=>{try{log("Fetching page HTML...");const n=await fetch(location.href,{credentials:"omit"});log("Fetch status",n.status);if(n.ok){const t=await n.text();log("HTML length",t.length);return t}}catch(e){log("Fetch failed",e)}log("Falling back to DOM HTML");return document.documentElement.outerHTML};const html=await h();log("Scan for URLs");const raw=html.match(r)||[];log("Raw matches",raw.length);const urls=[...new Set(raw.map(d).map(s).filter(Boolean))];log("Normalized unique URLs",urls.length);if(urls.length)log("Sample",urls.slice(0,3));if(!urls.length){alert("No photos found. Check console for details.");return}let i=1;for(const url of urls){const a=document.createElement("a");a.href=url;a.download="gbp-photo-"+("000"+i).slice(-3)+".jpg";document.body.appendChild(a);a.click();a.remove();i++}alert("Downloading "+urls.length+" photos.");})();
